-- =====================================================================
-- iGEN News — full working-newsroom seed (India Global Expo News).
-- 35 people with COMPLETE rich profiles, roles/memberships, and ~2 months of
-- FULL, mostly-published articles across the sectors (long-form bodies), plus
-- tasks, coverage and pitches. Preserves the 50 sectors + 1,348 industries.
-- Run AFTER seed-sectors.sql. Destructive to people/content only.
--   psql "$DATABASE_DIRECT_URL" -v ON_ERROR_STOP=1 -f scripts/seed-igennews.sql
-- =====================================================================
BEGIN;
SET search_path = meridian, public;

UPDATE desks SET lead_user_id = NULL;
TRUNCATE
  stories, pitches, tasks, coverage_events, desk_memberships, role_assignments,
  reviews, releases, release_attempts, corrections, story_versions, evidence, claims,
  comments, approvals, sources, source_access_grants, assets, drive_folders,
  notifications, notification_preferences, attention_states, dashboard_views,
  saved_searches, follows, favorites, recent_items, presence, feed_posts, feed_replies,
  feed_likes, feed_reposts, desk_invitations, desk_schedules, desk_slas,
  sector_applications, legal_documents, legal_document_parties, permission_policies,
  delegations, sessions, password_reset_tokens, audit_events, workflow_state_history,
  metric_snapshots, front_page_slots, workspace_branding
  RESTART IDENTITY CASCADE;
DELETE FROM users;
DELETE FROM desks WHERE settings->>'source' IS DISTINCT FROM 'India Global Expo — Master 50 Sectors';

