-- Stories: full, mostly-published, long-form bodies across ~2 months.
INSERT INTO stories
  (id, slug, title, dek, body, category, workflow_state, publication_state, priority,
   desk_id, sub_sector_id, author_id, editor_id, fact_checker_id, due_at, published_at, created_at, updated_at)
SELECT gen_random_uuid(), v.slug, v.title, v.dek, v.body::jsonb, v.category, v.wf, v.pub, v.pri,
  d.id, ss.id, au.id, ed.id, fc.id,
  CASE WHEN v.due_days IS NULL THEN NULL ELSE now() + make_interval(days => v.due_days) END,
  CASE WHEN v.pub='published' THEN now() - make_interval(hours => v.age_h) ELSE NULL END,
  now() - make_interval(hours => v.age_h), now() - make_interval(hours => (v.age_h/2))
FROM (VALUES
  ('ai-and-cyber-security', 'ai-and-cyber-security-ai-software-0-0', 'AI Software drives fresh momentum in India''s AI push', 'What the latest shifts in AI Software mean for the AI sector.', '[{"type": "heading", "text": "AI Software drives fresh momentum in India''s AI push"}, {"type": "paragraph", "text": "India''s AI Software is entering a defining stretch. Behind the headline numbers sits a more complicated story of capital, capacity and competition."}, {"type": "paragraph", "text": "Its scope is telling: AI algorithms, AI platforms, AI tools, AI SaaS products. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Executives across the AI sector describe a market in flux — demand is real, but margins are thin and the rules keep moving."}, {"type": "paragraph", "text": "“The demand is there. The question is whether we can build fast enough to meet it,” said a senior executive who asked not to be named."}, {"type": "paragraph", "text": "Smaller, faster companies are pushing into gaps the incumbents were slow to fill, forcing a rethink of who competes and how."}, {"type": "paragraph", "text": "By the numbers, AI Software has expanded for six straight quarters, and order books point to more of the same."}, {"type": "paragraph", "text": "Investors, once cautious, are now writing larger cheques, betting that scale arrives sooner than the sceptics expect."}, {"type": "paragraph", "text": "Whether AI Software becomes a story of steady growth or squandered advantage will depend on choices made this year."}]', 'AI & Cyber Security', 'ready', 'published', 'high', 'r.ai', 'e.tech', 'r.pillai', NULL, 0, NULL),
  ('ai-and-cyber-security', 'ai-and-cyber-security-computer-vision-1-1', 'The quiet transformation of Computer Vision', 'A ground-level look at computer vision and where it heads next.', '[{"type": "heading", "text": "The quiet transformation of Computer Vision"}, {"type": "paragraph", "text": "Ask anyone working in computer vision and you will hear the same thing: the fundamentals are strong, but the next eighteen months will decide who leads."}, {"type": "paragraph", "text": "Its scope is telling: Facial recognition, object detection, industrial inspection AI. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Talent is the other constraint. The specialists this work needs are scarce, and the competition for them is global."}, {"type": "paragraph", "text": "“The firms that invest through this cycle will own the next one,” an analyst tracking the sector said."}, {"type": "paragraph", "text": "Investors, once cautious, are now writing larger cheques, betting that scale arrives sooner than the sceptics expect."}, {"type": "paragraph", "text": "Hiring in computer vision is running well ahead of the wider AI sector, a sign of where the momentum sits."}, {"type": "paragraph", "text": "Executives across the AI sector describe a market in flux — demand is real, but margins are thin and the rules keep moving."}, {"type": "paragraph", "text": "The direction of travel is clear; the pace, and who benefits, is still being written."}]', 'AI & Cyber Security', 'ready', 'published', 'medium', 'r.ai', 'e.tech', NULL, NULL, 147, 'computer-vision-industry'),
  ('ai-and-cyber-security', 'ai-and-cyber-security-ai-cloud-platforms-2-2', 'AI Cloud Platforms faces a reckoning as demand shifts', 'The money, the policy and the players shaping AI Cloud Platforms.', '[{"type": "heading", "text": "AI Cloud Platforms faces a reckoning as demand shifts"}, {"type": "paragraph", "text": "India''s AI Cloud Platforms is entering a defining stretch. Behind the headline numbers sits a more complicated story of capital, capacity and competition."}, {"type": "paragraph", "text": "Its scope is telling: AI development environments hosted on cloud infrastructure. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Domestic demand is only half the story; export orders are increasingly where the growth — and the scrutiny — lies."}, {"type": "paragraph", "text": "“The demand is there. The question is whether we can build fast enough to meet it,” said a senior executive who asked not to be named."}, {"type": "paragraph", "text": "Executives across the AI sector describe a market in flux — demand is real, but margins are thin and the rules keep moving."}, {"type": "paragraph", "text": "By the numbers, AI Cloud Platforms has expanded for six straight quarters, and order books point to more of the same."}, {"type": "paragraph", "text": "Talent is the other constraint. The specialists this work needs are scarce, and the competition for them is global."}, {"type": "paragraph", "text": "Whether AI Cloud Platforms becomes a story of steady growth or squandered advantage will depend on choices made this year."}]', 'AI & Cyber Security', 'ready', 'published', 'low', 'r.ai', 'e.tech', 'r.pillai', NULL, 294, 'ai-cloud-platforms'),
  ('ai-and-cyber-security', 'ai-and-cyber-security-ai-healthcare-3-3', 'AI Healthcare: the supply-chain story behind the headlines', 'Why AI Healthcare has become one of the sector''s stories to watch.', '[{"type": "heading", "text": "AI Healthcare: the supply-chain story behind the headlines"}, {"type": "paragraph", "text": "Ask anyone working in AI Healthcare and you will hear the same thing: the fundamentals are strong, but the next eighteen months will decide who leads."}, {"type": "paragraph", "text": "Its scope is telling: Medical diagnosis AI, healthcare data analytics platforms. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Standards and compliance, long an afterthought, have moved to the centre of boardroom conversations."}, {"type": "paragraph", "text": "“The firms that invest through this cycle will own the next one,” an analyst tracking the sector said."}, {"type": "paragraph", "text": "Talent is the other constraint. The specialists this work needs are scarce, and the competition for them is global."}, {"type": "paragraph", "text": "Hiring in AI Healthcare is running well ahead of the wider AI sector, a sign of where the momentum sits."}, {"type": "paragraph", "text": "Domestic demand is only half the story; export orders are increasingly where the growth — and the scrutiny — lies."}, {"type": "paragraph", "text": "The direction of travel is clear; the pace, and who benefits, is still being written."}]', 'AI & Cyber Security', 'ready', 'published', 'high', 'r.ai', 'e.tech', NULL, NULL, 441, 'ai-healthcare-industry'),
  ('ai-and-cyber-security', 'ai-and-cyber-security-endpoint-security-solutions-4-4', 'Endpoint Security Solutions and the road to 2030', 'An iGEN News analysis of endpoint security solutions — the forces, the firms and the fault lines.', '[{"type": "heading", "text": "Endpoint Security Solutions and the road to 2030"}, {"type": "paragraph", "text": "India''s endpoint security solutions is entering a defining stretch. Behind the headline numbers sits a more complicated story of capital, capacity and competition."}, {"type": "paragraph", "text": "Its scope is telling: Antivirus, endpoint protection platforms, device security systems. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Supply chains that once ran on autopilot are being redrawn, with firms hedging against shortages and price swings."}, {"type": "paragraph", "text": "“The demand is there. The question is whether we can build fast enough to meet it,” said a senior executive who asked not to be named."}, {"type": "paragraph", "text": "Domestic demand is only half the story; export orders are increasingly where the growth — and the scrutiny — lies."}, {"type": "paragraph", "text": "By the numbers, endpoint security solutions has expanded for six straight quarters, and order books point to more of the same."}, {"type": "paragraph", "text": "Standards and compliance, long an afterthought, have moved to the centre of boardroom conversations."}, {"type": "paragraph", "text": "Whether endpoint security solutions becomes a story of steady growth or squandered advantage will depend on choices made this year."}]', 'AI & Cyber Security', 'ready', 'published', 'medium', 'r.ai', 'e.tech', 'r.pillai', NULL, 588, 'endpoint-security-solutions'),
  ('semiconductors', 'semiconductors-semiconductor-wafer-fabrication-5-0', 'How policy is reshaping Semiconductor Wafer Fabrication', 'What the latest shifts in semiconductor wafer fabrication mean for the Semiconductors sector.', '[{"type": "heading", "text": "How policy is reshaping Semiconductor Wafer Fabrication"}, {"type": "paragraph", "text": "For years semiconductor wafer fabrication sat in the background of the Semiconductors conversation. That is changing fast, and the pace has caught even insiders by surprise."}, {"type": "paragraph", "text": "Its scope is telling: Silicon wafer fabs, front-end IC manufacturing facilities. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Investors, once cautious, are now writing larger cheques, betting that scale arrives sooner than the sceptics expect."}, {"type": "paragraph", "text": "“We are two or three policy decisions away from this becoming a genuinely global business,” one industry veteran told iGEN News."}, {"type": "paragraph", "text": "Supply chains that once ran on autopilot are being redrawn, with firms hedging against shortages and price swings."}, {"type": "paragraph", "text": "Analysts now peg the addressable market in the tens of billions of dollars, up sharply from a year ago."}, {"type": "paragraph", "text": "Smaller, faster companies are pushing into gaps the incumbents were slow to fill, forcing a rethink of who competes and how."}, {"type": "paragraph", "text": "For the firms that get the next stretch right, the prize is a durable lead in a category that is only getting more strategic."}]', 'Semiconductors', 'ready', 'published', 'urgent', 'r.chip', 'e.tech', 'r.pillai', NULL, 600, NULL),
  ('semiconductors', 'semiconductors-memory-semiconductor-6-1', 'A new generation of firms bets on Memory Semiconductor', 'A ground-level look at memory semiconductor and where it heads next.', '[{"type": "heading", "text": "A new generation of firms bets on Memory Semiconductor"}, {"type": "paragraph", "text": "A wave of investment, policy attention and new entrants has turned memory semiconductor into one of the Semiconductors sector''s most closely watched corners."}, {"type": "paragraph", "text": "Its scope is telling: DRAM, NAND flash, NOR flash memory chip manufacturing. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Executives across the Semiconductors sector describe a market in flux — demand is real, but margins are thin and the rules keep moving."}, {"type": "paragraph", "text": "“Everyone underestimated how quickly this would move,” a founder in the space admitted."}, {"type": "paragraph", "text": "Smaller, faster companies are pushing into gaps the incumbents were slow to fill, forcing a rethink of who competes and how."}, {"type": "paragraph", "text": "Capital committed to memory semiconductor this year already exceeds the whole of last year, on some estimates."}, {"type": "paragraph", "text": "Investors, once cautious, are now writing larger cheques, betting that scale arrives sooner than the sceptics expect."}, {"type": "paragraph", "text": "One thing is certain: memory semiconductor will not look the same a year from now."}]', 'Semiconductors', 'ready', 'published', 'high', 'r.chip', 'e.tech', NULL, NULL, 747, 'memory-semiconductor-industry'),
  ('semiconductors', 'semiconductors-semiconductor-equipment-7-2', 'The numbers that explain Semiconductor Equipment right now', 'The money, the policy and the players shaping semiconductor equipment.', '[{"type": "heading", "text": "The numbers that explain Semiconductor Equipment right now"}, {"type": "paragraph", "text": "For years semiconductor equipment sat in the background of the Semiconductors conversation. That is changing fast, and the pace has caught even insiders by surprise."}, {"type": "paragraph", "text": "Its scope is telling: Photolithography, etch, CVD, CMP wafer processing tools. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Talent is the other constraint. The specialists this work needs are scarce, and the competition for them is global."}, {"type": "paragraph", "text": "“We are two or three policy decisions away from this becoming a genuinely global business,” one industry veteran told iGEN News."}, {"type": "paragraph", "text": "Investors, once cautious, are now writing larger cheques, betting that scale arrives sooner than the sceptics expect."}, {"type": "paragraph", "text": "Analysts now peg the addressable market in the tens of billions of dollars, up sharply from a year ago."}, {"type": "paragraph", "text": "Executives across the Semiconductors sector describe a market in flux — demand is real, but margins are thin and the rules keep moving."}, {"type": "paragraph", "text": "For the firms that get the next stretch right, the prize is a durable lead in a category that is only getting more strategic."}]', 'Semiconductors', 'desk_review', 'not_live', 'medium', 'r.chip', 'e.tech', NULL, 3, 894, 'semiconductor-equipment-industry'),
  ('semiconductors', 'semiconductors-chip-design-and-vlsi-services-8-3', 'Regulators sharpen their focus on Chip Design & VLSI Services', 'Why Chip Design & VLSI Services has become one of the sector''s stories to watch.', '[{"type": "heading", "text": "Regulators sharpen their focus on Chip Design & VLSI Services"}, {"type": "paragraph", "text": "A wave of investment, policy attention and new entrants has turned Chip Design & VLSI Services into one of the Semiconductors sector''s most closely watched corners."}, {"type": "paragraph", "text": "Its scope is telling: System-on-chip design, ASIC, FPGA, and IP development. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Domestic demand is only half the story; export orders are increasingly where the growth — and the scrutiny — lies."}, {"type": "paragraph", "text": "“Everyone underestimated how quickly this would move,” a founder in the space admitted."}, {"type": "paragraph", "text": "Executives across the Semiconductors sector describe a market in flux — demand is real, but margins are thin and the rules keep moving."}, {"type": "paragraph", "text": "Capital committed to Chip Design & VLSI Services this year already exceeds the whole of last year, on some estimates."}, {"type": "paragraph", "text": "Talent is the other constraint. The specialists this work needs are scarce, and the competition for them is global."}, {"type": "paragraph", "text": "One thing is certain: Chip Design & VLSI Services will not look the same a year from now."}]', 'Semiconductors', 'copy_standards', 'not_live', 'urgent', 'r.chip', 'e.tech', NULL, 4, 1041, 'chip-design-and-vlsi-services'),
  ('semiconductors', 'semiconductors-memory-chip-manufacturing-9-4', 'Capital, capacity and the future of Memory Chip Manufacturing', 'An iGEN News analysis of memory chip manufacturing — the forces, the firms and the fault lines.', '[{"type": "heading", "text": "Capital, capacity and the future of Memory Chip Manufacturing"}, {"type": "paragraph", "text": "For years memory chip manufacturing sat in the background of the Semiconductors conversation. That is changing fast, and the pace has caught even insiders by surprise."}, {"type": "paragraph", "text": "Its scope is telling: DRAM, NAND flash, and memory storage chip production. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Standards and compliance, long an afterthought, have moved to the centre of boardroom conversations."}, {"type": "paragraph", "text": "“We are two or three policy decisions away from this becoming a genuinely global business,” one industry veteran told iGEN News."}, {"type": "paragraph", "text": "Talent is the other constraint. The specialists this work needs are scarce, and the competition for them is global."}, {"type": "paragraph", "text": "Analysts now peg the addressable market in the tens of billions of dollars, up sharply from a year ago."}, {"type": "paragraph", "text": "Domestic demand is only half the story; export orders are increasingly where the growth — and the scrutiny — lies."}, {"type": "paragraph", "text": "For the firms that get the next stretch right, the prize is a durable lead in a category that is only getting more strategic."}]', 'Semiconductors', 'verification', 'not_live', 'high', 'r.chip', 'e.tech', NULL, 5, 1188, 'memory-chip-manufacturing'),
  ('technology', 'technology-ai-10-0', 'AI exports climb as global demand firms up', 'What the latest shifts in AI mean for the Technology sector.', '[{"type": "heading", "text": "AI exports climb as global demand firms up"}, {"type": "paragraph", "text": "Ask anyone working in AI and you will hear the same thing: the fundamentals are strong, but the next eighteen months will decide who leads."}, {"type": "paragraph", "text": "Its scope is telling: Development of intelligent systems capable of performing tasks that typically require human intelligence. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Smaller, faster companies are pushing into gaps the incumbents were slow to fill, forcing a rethink of who competes and how."}, {"type": "paragraph", "text": "“The firms that invest through this cycle will own the next one,” an analyst tracking the sector said."}, {"type": "paragraph", "text": "Standards and compliance, long an afterthought, have moved to the centre of boardroom conversations."}, {"type": "paragraph", "text": "Hiring in AI is running well ahead of the wider Technology sector, a sign of where the momentum sits."}, {"type": "paragraph", "text": "Supply chains that once ran on autopilot are being redrawn, with firms hedging against shortages and price swings."}, {"type": "paragraph", "text": "The direction of travel is clear; the pace, and who benefits, is still being written."}]', 'Technology', 'reporting', 'not_live', 'low', 'r.tech', 'e.tech', NULL, 1, 1200, NULL),
  ('technology', 'technology-iot-technology-11-1', 'IoT Technology at an inflection point', 'A ground-level look at iot technology and where it heads next.', '[{"type": "heading", "text": "IoT Technology at an inflection point"}, {"type": "paragraph", "text": "India''s iot technology is entering a defining stretch. Behind the headline numbers sits a more complicated story of capital, capacity and competition."}, {"type": "paragraph", "text": "Its scope is telling: Networks of connected devices that collect and exchange data. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Investors, once cautious, are now writing larger cheques, betting that scale arrives sooner than the sceptics expect."}, {"type": "paragraph", "text": "“The demand is there. The question is whether we can build fast enough to meet it,” said a senior executive who asked not to be named."}, {"type": "paragraph", "text": "Supply chains that once ran on autopilot are being redrawn, with firms hedging against shortages and price swings."}, {"type": "paragraph", "text": "By the numbers, iot technology has expanded for six straight quarters, and order books point to more of the same."}, {"type": "paragraph", "text": "Smaller, faster companies are pushing into gaps the incumbents were slow to fill, forcing a rethink of who competes and how."}, {"type": "paragraph", "text": "Whether iot technology becomes a story of steady growth or squandered advantage will depend on choices made this year."}]', 'Technology', 'ready', 'published', 'high', 'r.tech', 'e.tech', NULL, NULL, 1347, 'iot-technology'),
  ('technology', 'technology-data-analytics-12-2', 'Data Analytics drives fresh momentum in India''s Technology push', 'The money, the policy and the players shaping data analytics.', '[{"type": "heading", "text": "Data Analytics drives fresh momentum in India''s Technology push"}, {"type": "paragraph", "text": "Ask anyone working in data analytics and you will hear the same thing: the fundamentals are strong, but the next eighteen months will decide who leads."}, {"type": "paragraph", "text": "Its scope is telling: Analysis of large datasets to extract meaningful insights. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Executives across the Technology sector describe a market in flux — demand is real, but margins are thin and the rules keep moving."}, {"type": "paragraph", "text": "“The firms that invest through this cycle will own the next one,” an analyst tracking the sector said."}, {"type": "paragraph", "text": "Smaller, faster companies are pushing into gaps the incumbents were slow to fill, forcing a rethink of who competes and how."}, {"type": "paragraph", "text": "Hiring in data analytics is running well ahead of the wider Technology sector, a sign of where the momentum sits."}, {"type": "paragraph", "text": "Investors, once cautious, are now writing larger cheques, betting that scale arrives sooner than the sceptics expect."}, {"type": "paragraph", "text": "The direction of travel is clear; the pace, and who benefits, is still being written."}]', 'Technology', 'ready', 'published', 'medium', 'r.tech', 'e.tech', 'r.pillai', NULL, 54, 'data-analytics'),
  ('technology', 'technology-big-data-platforms-13-3', 'The quiet transformation of Big Data Platforms', 'Why big data platforms has become one of the sector''s stories to watch.', '[{"type": "heading", "text": "The quiet transformation of Big Data Platforms"}, {"type": "paragraph", "text": "India''s big data platforms is entering a defining stretch. Behind the headline numbers sits a more complicated story of capital, capacity and competition."}, {"type": "paragraph", "text": "Its scope is telling: Infrastructure designed to manage and process large volumes of data. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Talent is the other constraint. The specialists this work needs are scarce, and the competition for them is global."}, {"type": "paragraph", "text": "“The demand is there. The question is whether we can build fast enough to meet it,” said a senior executive who asked not to be named."}, {"type": "paragraph", "text": "Investors, once cautious, are now writing larger cheques, betting that scale arrives sooner than the sceptics expect."}, {"type": "paragraph", "text": "By the numbers, big data platforms has expanded for six straight quarters, and order books point to more of the same."}, {"type": "paragraph", "text": "Executives across the Technology sector describe a market in flux — demand is real, but margins are thin and the rules keep moving."}, {"type": "paragraph", "text": "Whether big data platforms becomes a story of steady growth or squandered advantage will depend on choices made this year."}]', 'Technology', 'ready', 'published', 'low', 'r.tech', 'e.tech', NULL, NULL, 201, 'big-data-platforms'),
  ('technology', 'technology-digital-payment-technology-14-4', 'Digital Payment Technology faces a reckoning as demand shifts', 'An iGEN News analysis of digital payment technology — the forces, the firms and the fault lines.', '[{"type": "heading", "text": "Digital Payment Technology faces a reckoning as demand shifts"}, {"type": "paragraph", "text": "Ask anyone working in digital payment technology and you will hear the same thing: the fundamentals are strong, but the next eighteen months will decide who leads."}, {"type": "paragraph", "text": "Its scope is telling: Technologies enabling secure online and mobile financial transactions. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Domestic demand is only half the story; export orders are increasingly where the growth — and the scrutiny — lies."}, {"type": "paragraph", "text": "“The firms that invest through this cycle will own the next one,” an analyst tracking the sector said."}, {"type": "paragraph", "text": "Executives across the Technology sector describe a market in flux — demand is real, but margins are thin and the rules keep moving."}, {"type": "paragraph", "text": "Hiring in digital payment technology is running well ahead of the wider Technology sector, a sign of where the momentum sits."}, {"type": "paragraph", "text": "Talent is the other constraint. The specialists this work needs are scarce, and the competition for them is global."}, {"type": "paragraph", "text": "The direction of travel is clear; the pace, and who benefits, is still being written."}]', 'Technology', 'ready', 'published', 'high', 'r.tech', 'e.tech', 'r.pillai', NULL, 348, 'digital-payment-technology'),
  ('banking-and-financial-services', 'banking-and-financial-services-securities-brokerage-15-0', 'Inside Securities Brokerage: what''s changing and who''s paying', 'What the latest shifts in securities brokerage mean for the Banking sector.', '[{"type": "heading", "text": "Inside Securities Brokerage: what''s changing and who''s paying"}, {"type": "paragraph", "text": "A wave of investment, policy attention and new entrants has turned securities brokerage into one of the Banking sector''s most closely watched corners."}, {"type": "paragraph", "text": "Its scope is telling: Stock broking, commodity brokering, online trading platforms. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Supply chains that once ran on autopilot are being redrawn, with firms hedging against shortages and price swings."}, {"type": "paragraph", "text": "“Everyone underestimated how quickly this would move,” a founder in the space admitted."}, {"type": "paragraph", "text": "Domestic demand is only half the story; export orders are increasingly where the growth — and the scrutiny — lies."}, {"type": "paragraph", "text": "Capital committed to securities brokerage this year already exceeds the whole of last year, on some estimates."}, {"type": "paragraph", "text": "Standards and compliance, long an afterthought, have moved to the centre of boardroom conversations."}, {"type": "paragraph", "text": "One thing is certain: securities brokerage will not look the same a year from now."}]', 'Banking & Financial Services', 'ready', 'published', 'medium', 'r.bank', 'e.fin', 'r.pillai', NULL, 360, NULL),
  ('banking-and-financial-services', 'banking-and-financial-services-small-finance-banks-16-1', 'Why investors are circling Small Finance Banks', 'A ground-level look at small finance banks and where it heads next.', '[{"type": "heading", "text": "Why investors are circling Small Finance Banks"}, {"type": "paragraph", "text": "For years small finance banks sat in the background of the Banking conversation. That is changing fast, and the pace has caught even insiders by surprise."}, {"type": "paragraph", "text": "Its scope is telling: Micro banking, priority sector lending for underserved segments. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Smaller, faster companies are pushing into gaps the incumbents were slow to fill, forcing a rethink of who competes and how."}, {"type": "paragraph", "text": "“We are two or three policy decisions away from this becoming a genuinely global business,” one industry veteran told iGEN News."}, {"type": "paragraph", "text": "Standards and compliance, long an afterthought, have moved to the centre of boardroom conversations."}, {"type": "paragraph", "text": "Analysts now peg the addressable market in the tens of billions of dollars, up sharply from a year ago."}, {"type": "paragraph", "text": "Supply chains that once ran on autopilot are being redrawn, with firms hedging against shortages and price swings."}, {"type": "paragraph", "text": "For the firms that get the next stretch right, the prize is a durable lead in a category that is only getting more strategic."}]', 'Banking & Financial Services', 'ready', 'published', 'urgent', 'r.bank', 'e.fin', NULL, NULL, 507, 'small-finance-banks-industry'),
