  ('retail-and-e-commerce', 'retail-and-e-commerce-shopping-mall-development-82-2', 'Shopping Mall Development drives fresh momentum in India''s Retail push', 'The money, the policy and the players shaping shopping mall development.', '[{"type": "heading", "text": "Shopping Mall Development drives fresh momentum in India''s Retail push"}, {"type": "paragraph", "text": "India''s shopping mall development is entering a defining stretch. Behind the headline numbers sits a more complicated story of capital, capacity and competition."}, {"type": "paragraph", "text": "Its scope is telling: Retail real estate, mall construction, and management. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Executives across the Retail sector describe a market in flux — demand is real, but margins are thin and the rules keep moving."}, {"type": "paragraph", "text": "“The demand is there. The question is whether we can build fast enough to meet it,” said a senior executive who asked not to be named."}, {"type": "paragraph", "text": "Smaller, faster companies are pushing into gaps the incumbents were slow to fill, forcing a rethink of who competes and how."}, {"type": "paragraph", "text": "By the numbers, shopping mall development has expanded for six straight quarters, and order books point to more of the same."}, {"type": "paragraph", "text": "Investors, once cautious, are now writing larger cheques, betting that scale arrives sooner than the sceptics expect."}, {"type": "paragraph", "text": "Whether shopping mall development becomes a story of steady growth or squandered advantage will depend on choices made this year."}]', 'Retail & E-Commerce', 'ready', 'published', 'high', 'r.retail', 'e.biz', 'r.pillai', NULL, 1254, 'shopping-mall-development'),
  ('retail-and-e-commerce', 'retail-and-e-commerce-fashion-retail-83-3', 'The quiet transformation of Fashion Retail', 'Why fashion retail has become one of the sector''s stories to watch.', '[{"type": "heading", "text": "The quiet transformation of Fashion Retail"}, {"type": "paragraph", "text": "Ask anyone working in fashion retail and you will hear the same thing: the fundamentals are strong, but the next eighteen months will decide who leads."}, {"type": "paragraph", "text": "Its scope is telling: Apparel, footwear, accessories retail and online channels. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Talent is the other constraint. The specialists this work needs are scarce, and the competition for them is global."}, {"type": "paragraph", "text": "“The firms that invest through this cycle will own the next one,” an analyst tracking the sector said."}, {"type": "paragraph", "text": "Investors, once cautious, are now writing larger cheques, betting that scale arrives sooner than the sceptics expect."}, {"type": "paragraph", "text": "Hiring in fashion retail is running well ahead of the wider Retail sector, a sign of where the momentum sits."}, {"type": "paragraph", "text": "Executives across the Retail sector describe a market in flux — demand is real, but margins are thin and the rules keep moving."}, {"type": "paragraph", "text": "The direction of travel is clear; the pace, and who benefits, is still being written."}]', 'Retail & E-Commerce', 'ready', 'published', 'medium', 'r.retail', 'e.biz', NULL, NULL, 1401, 'fashion-retail-industry'),
  ('retail-and-e-commerce', 'retail-and-e-commerce-hyperlocal-delivery-84-4', 'Hyperlocal Delivery faces a reckoning as demand shifts', 'An iGEN News analysis of hyperlocal delivery — the forces, the firms and the fault lines.', '[{"type": "heading", "text": "Hyperlocal Delivery faces a reckoning as demand shifts"}, {"type": "paragraph", "text": "India''s hyperlocal delivery is entering a defining stretch. Behind the headline numbers sits a more complicated story of capital, capacity and competition."}, {"type": "paragraph", "text": "Its scope is telling: 10-minute delivery, dark stores, quick commerce platforms. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Domestic demand is only half the story; export orders are increasingly where the growth — and the scrutiny — lies."}, {"type": "paragraph", "text": "“The demand is there. The question is whether we can build fast enough to meet it,” said a senior executive who asked not to be named."}, {"type": "paragraph", "text": "Executives across the Retail sector describe a market in flux — demand is real, but margins are thin and the rules keep moving."}, {"type": "paragraph", "text": "By the numbers, hyperlocal delivery has expanded for six straight quarters, and order books point to more of the same."}, {"type": "paragraph", "text": "Talent is the other constraint. The specialists this work needs are scarce, and the competition for them is global."}, {"type": "paragraph", "text": "Whether hyperlocal delivery becomes a story of steady growth or squandered advantage will depend on choices made this year."}]', 'Retail & E-Commerce', 'desk_review', 'not_live', 'low', 'r.retail', 'e.biz', NULL, 5, 108, 'hyperlocal-delivery-industry'),
  ('tourism', 'tourism-adventure-tourism-85-0', 'Inside Adventure Tourism: what''s changing and who''s paying', 'What the latest shifts in adventure tourism mean for the Tourism sector.', '[{"type": "heading", "text": "Inside Adventure Tourism: what''s changing and who''s paying"}, {"type": "paragraph", "text": "For years adventure tourism sat in the background of the Tourism conversation. That is changing fast, and the pace has caught even insiders by surprise."}, {"type": "paragraph", "text": "Its scope is telling: Travel experiences involving adventure activities such as trekking, rafting, and mountain climbing. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Supply chains that once ran on autopilot are being redrawn, with firms hedging against shortages and price swings."}, {"type": "paragraph", "text": "“We are two or three policy decisions away from this becoming a genuinely global business,” one industry veteran told iGEN News."}, {"type": "paragraph", "text": "Domestic demand is only half the story; export orders are increasingly where the growth — and the scrutiny — lies."}, {"type": "paragraph", "text": "Analysts now peg the addressable market in the tens of billions of dollars, up sharply from a year ago."}, {"type": "paragraph", "text": "Standards and compliance, long an afterthought, have moved to the centre of boardroom conversations."}, {"type": "paragraph", "text": "For the firms that get the next stretch right, the prize is a durable lead in a category that is only getting more strategic."}]', 'Tourism', 'copy_standards', 'not_live', 'high', 'r.tourism', 'e.biz', NULL, 1, 120, NULL),
  ('tourism', 'tourism-wellness-tourism-86-1', 'Why investors are circling Wellness Tourism', 'A ground-level look at wellness tourism and where it heads next.', '[{"type": "heading", "text": "Why investors are circling Wellness Tourism"}, {"type": "paragraph", "text": "A wave of investment, policy attention and new entrants has turned wellness tourism into one of the Tourism sector''s most closely watched corners."}, {"type": "paragraph", "text": "Its scope is telling: Travel focused on health, relaxation, and wellness activities such as spa treatments and yoga retreats. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Smaller, faster companies are pushing into gaps the incumbents were slow to fill, forcing a rethink of who competes and how."}, {"type": "paragraph", "text": "“Everyone underestimated how quickly this would move,” a founder in the space admitted."}, {"type": "paragraph", "text": "Standards and compliance, long an afterthought, have moved to the centre of boardroom conversations."}, {"type": "paragraph", "text": "Capital committed to wellness tourism this year already exceeds the whole of last year, on some estimates."}, {"type": "paragraph", "text": "Supply chains that once ran on autopilot are being redrawn, with firms hedging against shortages and price swings."}, {"type": "paragraph", "text": "One thing is certain: wellness tourism will not look the same a year from now."}]', 'Tourism', 'verification', 'not_live', 'medium', 'r.tourism', 'e.biz', NULL, 2, 267, 'wellness-tourism'),
  ('tourism', 'tourism-luxury-tourism-87-2', 'How policy is reshaping Luxury Tourism', 'The money, the policy and the players shaping luxury tourism.', '[{"type": "heading", "text": "How policy is reshaping Luxury Tourism"}, {"type": "paragraph", "text": "For years luxury tourism sat in the background of the Tourism conversation. That is changing fast, and the pace has caught even insiders by surprise."}, {"type": "paragraph", "text": "Its scope is telling: Premium travel experiences offering high-end services and exclusive accommodations. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Investors, once cautious, are now writing larger cheques, betting that scale arrives sooner than the sceptics expect."}, {"type": "paragraph", "text": "“We are two or three policy decisions away from this becoming a genuinely global business,” one industry veteran told iGEN News."}, {"type": "paragraph", "text": "Supply chains that once ran on autopilot are being redrawn, with firms hedging against shortages and price swings."}, {"type": "paragraph", "text": "Analysts now peg the addressable market in the tens of billions of dollars, up sharply from a year ago."}, {"type": "paragraph", "text": "Smaller, faster companies are pushing into gaps the incumbents were slow to fill, forcing a rethink of who competes and how."}, {"type": "paragraph", "text": "For the firms that get the next stretch right, the prize is a durable lead in a category that is only getting more strategic."}]', 'Tourism', 'reporting', 'not_live', 'urgent', 'r.tourism', 'e.biz', NULL, 3, 414, 'luxury-tourism'),
  ('tourism', 'tourism-culinary-tourism-88-3', 'A new generation of firms bets on Culinary Tourism', 'Why culinary tourism has become one of the sector''s stories to watch.', '[{"type": "heading", "text": "A new generation of firms bets on Culinary Tourism"}, {"type": "paragraph", "text": "A wave of investment, policy attention and new entrants has turned culinary tourism into one of the Tourism sector''s most closely watched corners."}, {"type": "paragraph", "text": "Its scope is telling: Tourism focused on experiencing local food culture and culinary traditions. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Executives across the Tourism sector describe a market in flux — demand is real, but margins are thin and the rules keep moving."}, {"type": "paragraph", "text": "“Everyone underestimated how quickly this would move,” a founder in the space admitted."}, {"type": "paragraph", "text": "Smaller, faster companies are pushing into gaps the incumbents were slow to fill, forcing a rethink of who competes and how."}, {"type": "paragraph", "text": "Capital committed to culinary tourism this year already exceeds the whole of last year, on some estimates."}, {"type": "paragraph", "text": "Investors, once cautious, are now writing larger cheques, betting that scale arrives sooner than the sceptics expect."}, {"type": "paragraph", "text": "One thing is certain: culinary tourism will not look the same a year from now."}]', 'Tourism', 'ready', 'published', 'high', 'r.tourism', 'e.biz', NULL, NULL, 561, 'culinary-tourism'),
  ('tourism', 'tourism-adventure-sports-tourism-89-4', 'The numbers that explain Adventure Sports Tourism right now', 'An iGEN News analysis of adventure sports tourism — the forces, the firms and the fault lines.', '[{"type": "heading", "text": "The numbers that explain Adventure Sports Tourism right now"}, {"type": "paragraph", "text": "For years adventure sports tourism sat in the background of the Tourism conversation. That is changing fast, and the pace has caught even insiders by surprise."}, {"type": "paragraph", "text": "Its scope is telling: Tourism centered on extreme sports such as skydiving, rock climbing, and paragliding. That breadth is both its strength and, increasingly, its challenge."}, {"type": "paragraph", "text": "Talent is the other constraint. The specialists this work needs are scarce, and the competition for them is global."}, {"type": "paragraph", "text": "“We are two or three policy decisions away from this becoming a genuinely global business,” one industry veteran told iGEN News."}, {"type": "paragraph", "text": "Investors, once cautious, are now writing larger cheques, betting that scale arrives sooner than the sceptics expect."}, {"type": "paragraph", "text": "Analysts now peg the addressable market in the tens of billions of dollars, up sharply from a year ago."}, {"type": "paragraph", "text": "Executives across the Tourism sector describe a market in flux — demand is real, but margins are thin and the rules keep moving."}, {"type": "paragraph", "text": "For the firms that get the next stretch right, the prize is a durable lead in a category that is only getting more strategic."}]', 'Tourism', 'ready', 'published', 'medium', 'r.tourism', 'e.biz', 'r.pillai', NULL, 708, 'adventure-sports-tourism')
) AS v(sector_slug, slug, title, dek, body, category, wf, pub, pri, author_handle, editor_handle, fc_handle, due_days, age_h, ind_slug)
JOIN desks d ON d.slug=v.sector_slug JOIN users au ON au.handle=v.author_handle JOIN users ed ON ed.handle=v.editor_handle
LEFT JOIN users fc ON fc.handle=v.fc_handle LEFT JOIN sub_sectors ss ON ss.desk_id=d.id AND ss.slug=v.ind_slug;

-- Front page: feature the most recent published stories.
INSERT INTO front_page_slots (id, position, label, story_id, is_pinned, updated_by_id, updated_at)
SELECT gen_random_uuid(), v.position, v.label, s.id, v.pinned, a.id, now() FROM (VALUES
  (1, 'Lead', 'ai-and-cyber-security-ai-software-0-0', true),
  (2, 'Top story', 'ai-and-cyber-security-computer-vision-1-1', false),
  (3, 'Also featured', 'ai-and-cyber-security-ai-cloud-platforms-2-2', false),
  (4, 'Also featured', 'ai-and-cyber-security-ai-healthcare-3-3', false),
  (5, 'Also featured', 'ai-and-cyber-security-endpoint-security-solutions-4-4', false),
  (6, 'Also featured', 'semiconductors-semiconductor-wafer-fabrication-5-0', false)
) AS v(position, label, slug, pinned) JOIN stories s ON s.slug=v.slug CROSS JOIN (SELECT id FROM users WHERE handle='admin') a;

