SELECT gen_random_uuid(), v.title, v.description, d.id, o.id, now() + make_interval(days => v.start_days, hours => 9), now() + make_interval(days => v.start_days, hours => 12), v.status, v.location, '{}'::jsonb, now(), now() FROM (VALUES
