  ('Union Budget: sector briefings', 'Finance ministry post-budget briefings.', 'banking-and-financial-services', 'r.bank', 3, 'New Delhi', 'confirmed'),
  ('EV manufacturing plant opening', 'New gigafactory inauguration.', 'automotive-and-electric-vehicles', 'r.auto', 5, 'Pune', 'planned'),
  ('ISRO launch window', 'Next satellite launch briefing.', 'space', 'r.space', 6, 'Sriharikota', 'tentative'),
  ('Renewables capacity auction', 'Solar and wind capacity results.', 'new-and-renewable-energy', 'r.renew', 4, 'Chennai', 'planned'),
  ('Semiconductor fab groundbreaking', 'New chip fabrication facility.', 'semiconductors', 'r.chip', 8, 'Hyderabad', 'planned'),
  ('National health mission review', 'Annual programme review.', 'health-and-family-welfare', 'r.health', 7, 'New Delhi', 'tentative'),
  ('Defence expo', 'Aerospace and defence exhibition.', 'defence-and-aerospace', 'r.def', 10, 'New Delhi', 'confirmed')
) AS v(title, description, sector_slug, owner_handle, start_days, location, status) JOIN desks d ON d.slug=v.sector_slug JOIN users o ON o.handle=v.owner_handle;

