) AS v(headline, summary, angle, sector_slug, creator, assignee, editor, status, priority, age_h) JOIN desks d ON d.slug=v.sector_slug JOIN users cr ON cr.handle=v.creator LEFT JOIN users asg ON asg.handle=v.assignee JOIN users ed ON ed.handle=v.editor;

COMMIT;

SELECT 'users' AS entity, count(*) FROM users
UNION ALL SELECT 'profiles_rich', count(*) FROM users WHERE profile ? 'headline' AND profile->>'headline' <> ''
UNION ALL SELECT 'stories', count(*) FROM stories
UNION ALL SELECT 'stories_published', count(*) FROM stories WHERE publication_state='published'
UNION ALL SELECT 'stories_with_industry', count(*) FROM stories WHERE sub_sector_id IS NOT NULL
UNION ALL SELECT 'avg_body_blocks', round(avg(jsonb_array_length(body)))::text::int FROM stories
UNION ALL SELECT 'feed_posts', count(*) FROM feed_posts
UNION ALL SELECT 'front_page_slots', count(*) FROM front_page_slots
UNION ALL SELECT 'tasks', count(*) FROM tasks
UNION ALL SELECT 'pitches', count(*) FROM pitches
UNION ALL SELECT 'coverage_events', count(*) FROM coverage_events
ORDER BY entity;